CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, openId TEXT NOT NULL UNIQUE, name TEXT, email TEXT, loginMethod TEXT, role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')), createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, lastSignedIn INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS scans (id INTEGER PRIMARY KEY AUTOINCREMENT, userId INTEGER NOT NULL, targetUrl TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'completed' CHECK (status IN ('completed','failed')), criticalCount INTEGER NOT NULL DEFAULT 0, highCount INTEGER NOT NULL DEFAULT 0, mediumCount INTEGER NOT NULL DEFAULT 0, lowCount INTEGER NOT NULL DEFAULT 0, infoCount INTEGER NOT NULL DEFAULT 0, summary TEXT, createdAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS findings (id INTEGER PRIMARY KEY AUTOINCREMENT, scanId INTEGER NOT NULL, category TEXT NOT NULL, severity TEXT NOT NULL CHECK (severity IN ('Critical','High','Medium','Low','Info')), title TEXT NOT NULL, description TEXT NOT NULL, remediation TEXT NOT NULL, evidence TEXT, createdAt INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS scans_user_created_idx ON scans(userId, createdAt DESC);
CREATE INDEX IF NOT EXISTS findings_scan_idx ON findings(scanId, id);
